/* OnePageIRC
 * A single page IRC client. No frameworks, no build step, no dependencies.
 *
 * Generated by AI Sloperator <https://www.aisloperator.com/> using Claude Code.
 *
 * Transport note: a web page cannot open a raw TCP socket, so this client
 * speaks IRC over a WebSocket. The host/port you enter must therefore accept
 * WebSocket connections (many ircds can, and gateways such as
 * kiwiirc/webircgateway provide one in front of an ordinary ircd).
 */
'use strict';

(function () {

/* ------------------------------------------------------------------ util */

const $ = (sel, root) => (root || document).querySelector(sel);

function el(tag, cls, text) {
  const n = document.createElement(tag);
  if (cls) n.className = cls;
  if (text != null) n.textContent = text;
  return n;
}

function pad2(n) { return n < 10 ? '0' + n : '' + n; }

function timestamp(date) {
  const d = date || new Date();
  return pad2(d.getHours()) + ':' + pad2(d.getMinutes());
}

/* IRC casemapping (rfc1459): {}|^ are the lowercase of []\~ */
function ircLower(s) {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c === '[') out += '{';
    else if (c === ']') out += '}';
    else if (c === '\\') out += '|';
    else if (c === '~') out += '^';
    else out += c.toLowerCase();
  }
  return out;
}

function hashCode(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  return Math.abs(h);
}

function nickColor(nick) {
  /* Comma syntax: widest support. The saturation/lightness come from the
     theme so nicks stay readable in both light and dark. */
  return 'hsl(' + (hashCode(ircLower(nick)) % 360) + ', var(--nick-sat), var(--nick-lum))';
}

function randomNick() {
  let d = '';
  const c = window.crypto;
  if (c && c.getRandomValues) {
    const r = new Uint32Array(8);
    c.getRandomValues(r);
    for (let i = 0; i < 8; i++) d += (r[i] % 10);
  } else {
    for (let i = 0; i < 8; i++) d += Math.floor(Math.random() * 10);
  }
  return 'user' + d;
}

function b64utf8(str) {
  const bytes = new TextEncoder().encode(str);
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

/* ------------------------------------------------------- protocol parsing */

/* Parse one IRC line into { tags, prefix, nick, user, host, command, params } */
function parseLine(line) {
  const msg = { tags: {}, prefix: '', nick: '', user: '', host: '', command: '', params: [] };
  let rest = line;

  if (rest.charAt(0) === '@') {
    const sp = rest.indexOf(' ');
    const raw = rest.slice(1, sp < 0 ? rest.length : sp);
    rest = sp < 0 ? '' : rest.slice(sp + 1);
    raw.split(';').forEach(function (pair) {
      if (!pair) return;
      const eq = pair.indexOf('=');
      const k = eq < 0 ? pair : pair.slice(0, eq);
      const v = eq < 0 ? '' : pair.slice(eq + 1);
      msg.tags[k] = unescapeTag(v);
    });
    rest = rest.replace(/^ +/, '');
  }

  if (rest.charAt(0) === ':') {
    const sp = rest.indexOf(' ');
    msg.prefix = rest.slice(1, sp < 0 ? rest.length : sp);
    rest = sp < 0 ? '' : rest.slice(sp + 1).replace(/^ +/, '');
    const bang = msg.prefix.indexOf('!');
    const at = msg.prefix.indexOf('@');
    if (bang > 0) {
      msg.nick = msg.prefix.slice(0, bang);
      msg.user = at > bang ? msg.prefix.slice(bang + 1, at) : msg.prefix.slice(bang + 1);
      msg.host = at > bang ? msg.prefix.slice(at + 1) : '';
    } else if (at > 0) {
      msg.nick = msg.prefix.slice(0, at);
      msg.host = msg.prefix.slice(at + 1);
    } else {
      msg.nick = msg.prefix;
    }
  }

  while (rest.length) {
    if (rest.charAt(0) === ':') { msg.params.push(rest.slice(1)); rest = ''; break; }
    const sp = rest.indexOf(' ');
    if (sp < 0) { msg.params.push(rest); rest = ''; break; }
    msg.params.push(rest.slice(0, sp));
    rest = rest.slice(sp + 1).replace(/^ +/, '');
  }

  msg.command = (msg.params.shift() || '').toUpperCase();
  return msg;
}

function unescapeTag(v) {
  let out = '';
  for (let i = 0; i < v.length; i++) {
    if (v[i] === '\\' && i + 1 < v.length) {
      const n = v[++i];
      out += n === ':' ? ';' : n === 's' ? ' ' : n === 'r' ? '\r' : n === 'n' ? '\n' : n;
    } else out += v[i];
  }
  return out;
}

/* ------------------------------------------------------------- app state */

const STORE_KEY = 'onepageirc.settings.v1';

const state = {
  ws: null,
  status: 'offline',          /* offline | connecting | registering | online */
  settings: null,
  nick: '',
  serverName: '',
  network: '',
  tabs: [],
  byId: new Map(),
  active: null,
  isupport: {
    PREFIX: { modes: 'ov', prefixes: '@+' },
    CHANTYPES: '#&',
    CHANMODES: ['beI', 'k', 'l', 'imnpstrDdRcCNuMTGPZQ']
  },
  caps: { available: {}, enabled: {}, requested: 0, negotiating: false },
  history: [],
  histIndex: -1,
  histDraft: '',
  pendingJoin: [],
  nickTries: 0,
  quitting: false
};

const WANTED_CAPS = [
  'multi-prefix', 'server-time', 'away-notify', 'account-notify',
  'chghost', 'extended-join', 'userhost-in-names', 'message-tags',
  'echo-message', 'invite-notify', 'sasl'
];

/* --------------------------------------------------------------- element */

const ui = {
  app: $('#app'),
  topbar: $('#topbar'),
  titleName: $('#title-name'),
  titleSub: $('#title-sub'),
  tabbar: $('#tabbar'),
  main: $('#main'),
  views: $('#views'),
  userlist: $('#userlist'),
  userCount: $('#userlist-count'),
  userItems: $('#userlist-items'),
  scrim: $('#scrim'),
  btnUsers: $('#btn-users'),
  btnMenu: $('#btn-menu'),
  input: $('#input'),
  composer: $('#composer'),
  dialog: $('#connect-dialog'),
  form: $('#connect-form'),
  dlgError: $('#connect-error'),
  dlgNote: $('#connect-note'),
  btnCancel: $('#btn-cancel')
};

/* ------------------------------------------------------------------ tabs */

function tabId(type, name) {
  return type === 'system' ? 'system' : type + ':' + ircLower(name);
}

function isChannel(name) {
  return name && state.isupport.CHANTYPES.indexOf(name.charAt(0)) >= 0;
}

function getTab(type, name) {
  return state.byId.get(tabId(type, name)) || null;
}

function findTab(name) {
  return getTab(isChannel(name) ? 'channel' : 'query', name);
}

function createTab(type, name) {
  const id = tabId(type, name);
  const existing = state.byId.get(id);
  if (existing) return existing;

  const tab = {
    id: id,
    type: type,
    name: type === 'system' ? 'Server' : name,
    users: new Map(),
    topic: '',
    joined: type !== 'channel',
    unread: 0,
    hl: false,
    stick: true
  };

  tab.log = el('div', 'log');
  tab.log.hidden = true;
  tab.topicEl = el('div', 'topicbar');
  tab.topicEl.hidden = true;
  tab.log.appendChild(tab.topicEl);
  tab.log.addEventListener('scroll', function () {
    tab.stick = tab.log.scrollTop + tab.log.clientHeight >= tab.log.scrollHeight - 40;
  }, { passive: true });
  ui.views.appendChild(tab.log);

  tab.btn = el('div', 'tab');
  tab.btn.setAttribute('role', 'button');
  tab.btn.tabIndex = 0;
  const nameEl = el('span', 'tab-name', tab.name);
  const badge = el('span', 'badge', '');
  badge.hidden = true;
  tab.nameEl = nameEl;
  tab.badge = badge;
  tab.btn.appendChild(nameEl);
  tab.btn.appendChild(badge);
  if (type !== 'system') {
    const close = el('button', 'close', '×');
    close.type = 'button';
    close.title = 'Close';
    close.setAttribute('aria-label', 'Close ' + tab.name);
    close.addEventListener('click', function (ev) {
      ev.stopPropagation();
      closeTab(tab);
    });
    tab.btn.appendChild(close);
  }
  tab.btn.addEventListener('click', function () { activateTab(tab); });
  tab.btn.addEventListener('keydown', function (ev) {
    if (ev.key === 'Enter' || ev.key === ' ') { ev.preventDefault(); activateTab(tab); }
  });
  ui.tabbar.appendChild(tab.btn);

  state.tabs.push(tab);
  state.byId.set(id, tab);
  return tab;
}

function activateTab(tab) {
  if (!tab) return;
  if (state.active === tab) { scrollDown(tab); return; }
  if (state.active) {
    state.active.log.hidden = true;
    state.active.btn.classList.remove('active');
  }
  state.active = tab;
  tab.log.hidden = false;
  tab.btn.classList.add('active');
  tab.unread = 0;
  tab.hl = false;
  updateBadge(tab);
  updateChrome();
  renderUsers();
  scrollDown(tab);
  try {
    tab.btn.scrollIntoView({ block: 'nearest', inline: 'nearest' });
  } catch (e) { /* older engines */ }
}

function closeTab(tab) {
  if (tab.type === 'system') return;
  if (tab.type === 'channel' && tab.joined && state.status === 'online') {
    send('PART ' + tab.name);
  }
  const i = state.tabs.indexOf(tab);
  state.tabs.splice(i, 1);
  state.byId.delete(tab.id);
  tab.log.remove();
  tab.btn.remove();
  if (state.active === tab) {
    state.active = null;
    activateTab(state.tabs[Math.min(i, state.tabs.length - 1)] || state.tabs[0]);
  }
}

function renameTab(tab, name) {
  state.byId.delete(tab.id);
  tab.name = name;
  tab.id = tabId(tab.type, name);
  tab.nameEl.textContent = name;
  state.byId.set(tab.id, tab);
  if (state.active === tab) updateChrome();
}

function updateBadge(tab) {
  tab.badge.textContent = tab.unread > 99 ? '99+' : String(tab.unread);
  tab.badge.hidden = tab.unread === 0;
  tab.btn.classList.toggle('hl', tab.hl);
  tab.btn.classList.toggle('parted', tab.type === 'channel' && !tab.joined);
  updateTitle();
}

function updateTitle() {
  let n = 0, hl = false;
  state.tabs.forEach(function (t) { n += t.unread; if (t.hl) hl = true; });
  document.title = (n ? (hl ? '(*' + n + ') ' : '(' + n + ') ') : '') + 'OnePageIRC';
}

function bump(tab, highlight) {
  if (state.active === tab && document.visibilityState === 'visible') return;
  tab.unread++;
  if (highlight) tab.hl = true;
  updateBadge(tab);
}

function systemTab() { return state.byId.get('system'); }

function targetTab(name) {
  return findTab(name) || systemTab();
}

/* -------------------------------------------------------------- chrome */

function updateChrome() {
  const tab = state.active;
  const isChan = !!tab && tab.type === 'channel';
  ui.btnUsers.hidden = !isChan;
  ui.main.classList.toggle('with-users', isChan && usersOpen());
  ui.userlist.hidden = !(isChan && usersOpen());
  ui.scrim.hidden = !(isChan && usersOpen() && window.innerWidth < 700);

  if (!tab) return;
  if (tab.type === 'system') {
    ui.titleName.textContent = state.serverName || state.network ||
      (state.settings ? state.settings.server : 'OnePageIRC');
  } else {
    ui.titleName.textContent = tab.name;
  }

  const s = state.status;
  let sub;
  if (s === 'online') sub = state.nick + ' · ' + (state.network || state.serverName || state.settings.server);
  else if (s === 'registering') sub = 'registering…';
  else if (s === 'connecting') sub = 'connecting…';
  else sub = 'not connected — tap ☰ to connect';
  ui.titleSub.textContent = sub;
  ui.titleSub.className = s === 'online' ? 'on' : s === 'offline' ? 'off' : '';
}

let usersVisible = window.innerWidth >= 700;
function usersOpen() { return usersVisible; }

ui.btnUsers.addEventListener('click', function () {
  usersVisible = !usersVisible;
  ui.btnUsers.setAttribute('aria-expanded', String(usersVisible));
  updateChrome();
  renderUsers();
});
ui.scrim.addEventListener('click', function () {
  usersVisible = false;
  ui.btnUsers.setAttribute('aria-expanded', 'false');
  updateChrome();
});

/* ------------------------------------------------------- message output */

const MIRC = ['#ffffff', '#000000', '#00007f', '#009300', '#ff0000', '#7f0000',
              '#9c009c', '#fc7f00', '#ffff00', '#00fc00', '#009393', '#00ffff',
              '#0000fc', '#ff00ff', '#7f7f7f', '#d2d2d2'];

const TOKEN_RE = /((?:https?:\/\/|www\.)[^\s<>"'`]+)|(^|[\s(<])([#&][^\s,()<>]{1,60})/g;

function linkify(parent, text) {
  TOKEN_RE.lastIndex = 0;
  let last = 0, m;
  while ((m = TOKEN_RE.exec(text)) !== null) {
    if (m[1]) {
      let url = m[1];
      /* Do not swallow trailing sentence punctuation. */
      let trimmed = url.replace(/[.,;:!?'"’]+$/, '');
      while (trimmed.charAt(trimmed.length - 1) === ')' &&
             (trimmed.split(')').length - trimmed.split('(').length) > 0) {
        trimmed = trimmed.slice(0, -1);
      }
      if (m.index > last) parent.appendChild(document.createTextNode(text.slice(last, m.index)));
      const a = el('a', null, trimmed);
      a.href = /^www\./i.test(trimmed) ? 'https://' + trimmed : trimmed;
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      parent.appendChild(a);
      last = m.index + trimmed.length;
      TOKEN_RE.lastIndex = last;
    } else {
      const lead = m[2] || '';
      const chan = m[3].replace(/[.,;:!?'"]+$/, '');
      const start = m.index + lead.length;
      if (chan.length < 2) { TOKEN_RE.lastIndex = start + m[3].length; continue; }
      if (start > last) parent.appendChild(document.createTextNode(text.slice(last, start)));
      const a = el('a', 'chan', chan);
      a.href = '#';
      a.addEventListener('click', function (ev) {
        ev.preventDefault();
        const t = getTab('channel', chan);
        if (t) activateTab(t); else runCommand('join', chan);
      });
      parent.appendChild(a);
      last = start + chan.length;
      TOKEN_RE.lastIndex = last;
    }
  }
  if (last < text.length) parent.appendChild(document.createTextNode(text.slice(last)));
}

/* Turn IRC formatting codes into styled spans. */
function formatBody(text) {
  const frag = document.createDocumentFragment();
  let buf = '';
  let st = { b: false, i: false, u: false, s: false, fg: null, bg: null };

  function flush() {
    if (!buf) return;
    if (!st.b && !st.i && !st.u && !st.s && st.fg == null && st.bg == null) {
      linkify(frag, buf);
    } else {
      let cls = '';
      if (st.b) cls += ' b';
      if (st.i) cls += ' i';
      if (st.u) cls += ' u';
      if (st.s) cls += ' s';
      const span = el('span', cls.trim() || null);
      if (st.fg != null && MIRC[st.fg]) span.style.color = MIRC[st.fg];
      if (st.bg != null && MIRC[st.bg]) span.style.backgroundColor = MIRC[st.bg];
      linkify(span, buf);
      frag.appendChild(span);
    }
    buf = '';
  }

  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    if (c === 2) { flush(); st.b = !st.b; }
    else if (c === 29) { flush(); st.i = !st.i; }
    else if (c === 31) { flush(); st.u = !st.u; }
    else if (c === 30) { flush(); st.s = !st.s; }
    else if (c === 15) { flush(); st = { b: false, i: false, u: false, s: false, fg: null, bg: null }; }
    else if (c === 22) { flush(); /* reverse: ignored */ }
    else if (c === 3) {
      flush();
      let j = i + 1, num = '';
      while (j < text.length && num.length < 2 && text[j] >= '0' && text[j] <= '9') num += text[j++];
      if (!num) { st.fg = null; st.bg = null; i = j - 1; continue; }
      st.fg = parseInt(num, 10);
      st.bg = null;
      if (text[j] === ',' && text[j + 1] >= '0' && text[j + 1] <= '9') {
        j++;
        let num2 = '';
        while (j < text.length && num2.length < 2 && text[j] >= '0' && text[j] <= '9') num2 += text[j++];
        st.bg = parseInt(num2, 10);
      }
      i = j - 1;
    }
    else if (c === 4) { /* hex colour: skip 6 digits */ flush(); i += 6; }
    else buf += text[i];
  }
  flush();
  return frag;
}

const MAX_LINES = 1200;

/* kind: message | self | action | event | notice | error | system | motd | raw */
function print(tab, kind, who, body, opts) {
  const o = opts || {};
  const line = el('div', 'line ' + kind + (o.highlight ? ' hl' : ''));

  line.appendChild(el('span', 'ts', timestamp(o.time)));

  const whoEl = el('span', 'who', who == null ? '' : who);
  if (o.nick) whoEl.style.color = nickColor(o.nick);
  else if (kind === 'event' || kind === 'system') whoEl.style.color = '';
  line.appendChild(whoEl);

  const bodyEl = el('span', 'body');
  if (o.plain) bodyEl.textContent = body;
  else bodyEl.appendChild(formatBody(body));
  line.appendChild(bodyEl);

  tab.log.appendChild(line);

  let extra = tab.log.childElementCount - 1 - MAX_LINES;
  while (extra-- > 0) {
    const first = tab.log.firstElementChild === tab.topicEl
      ? tab.topicEl.nextElementSibling : tab.log.firstElementChild;
    if (!first) break;
    first.remove();
  }

  if (tab.stick) scrollDown(tab);
  return line;
}

function scrollDown(tab) {
  tab.stick = true;
  tab.log.scrollTop = tab.log.scrollHeight;
}

function sys(body, kind) {
  print(systemTab(), kind || 'system', '*', body, { plain: kind === 'raw' });
}

function event(tab, body) {
  print(tab, 'event', '*', body, { plain: true });
}

function errline(tab, body) {
  print(tab || systemTab(), 'error', '*', body, { plain: true });
}

/* --------------------------------------------------------------- users */

function prefixRank(prefixes) {
  const order = state.isupport.PREFIX.prefixes;
  let best = order.length;
  for (let i = 0; i < prefixes.length; i++) {
    const idx = order.indexOf(prefixes[i]);
    if (idx >= 0 && idx < best) best = idx;
  }
  return best;
}

function addUser(tab, nick, prefixes) {
  tab.users.set(ircLower(nick), { nick: nick, prefixes: prefixes || '', away: false });
  if (tab === state.active) scheduleUsers();
}

function removeUser(tab, nick) {
  if (tab.users.delete(ircLower(nick)) && tab === state.active) scheduleUsers();
}

function getUser(tab, nick) { return tab.users.get(ircLower(nick)) || null; }

let usersPending = false;
function scheduleUsers() {
  if (usersPending) return;
  usersPending = true;
  requestAnimationFrame(function () { usersPending = false; renderUsers(); });
}

function renderUsers() {
  const tab = state.active;
  if (!tab || tab.type !== 'channel' || ui.userlist.hidden) return;
  const list = [];
  tab.users.forEach(function (u) { list.push(u); });
  list.sort(function (a, b) {
    const ra = prefixRank(a.prefixes), rb = prefixRank(b.prefixes);
    if (ra !== rb) return ra - rb;
    return ircLower(a.nick) < ircLower(b.nick) ? -1 : 1;
  });

  ui.userCount.textContent = list.length + (list.length === 1 ? ' user' : ' users');
  const frag = document.createDocumentFragment();
  list.forEach(function (u) {
    const li = el('li', u.away ? 'away' : null);
    const top = u.prefixes ? u.prefixes.charAt(0) : '';
    if (top) li.appendChild(el('span', 'pfx', top));
    const name = el('span', null, u.nick);
    name.style.color = nickColor(u.nick);
    li.appendChild(name);
    li.addEventListener('click', function () {
      const t = createTab('query', u.nick);
      activateTab(t);
      if (window.innerWidth < 700) { usersVisible = false; updateChrome(); }
    });
    frag.appendChild(li);
  });
  ui.userItems.replaceChildren(frag);
}

function forEachChannelWith(nick, fn) {
  const key = ircLower(nick);
  state.tabs.forEach(function (t) {
    if (t.type === 'channel' && t.users.has(key)) fn(t);
  });
}

/* ---------------------------------------------------------- connection */

function wsUrl(s) {
  const scheme = s.tls ? 'wss' : 'ws';
  let path = s.path || '/';
  if (path.charAt(0) !== '/') path = '/' + path;
  const host = s.server.indexOf(':') >= 0 && s.server.charAt(0) !== '[' ? '[' + s.server + ']' : s.server;
  return scheme + '://' + host + ':' + s.port + path;
}

function setStatus(s) {
  state.status = s;
  updateChrome();
}

function connect() {
  disconnect(true);
  const s = state.settings;
  state.quitting = false;
  state.nick = s.nick;
  state.nickTries = 0;
  state.serverName = '';
  state.network = '';
  state.caps = { available: {}, enabled: {}, requested: 0, negotiating: false };
  state.pendingJoin = (s.channels || '').split(/[\s,]+/).filter(Boolean);
  motdSeen = false;

  const url = wsUrl(s);
  setStatus('connecting');
  sys('Connecting to ' + url + ' as ' + s.nick + ' …');

  let ws;
  try {
    ws = s.proto ? new WebSocket(url, s.proto) : new WebSocket(url);
  } catch (e) {
    setStatus('offline');
    errline(null, 'Could not open WebSocket: ' + e.message);
    return;
  }
  ws.binaryType = 'arraybuffer';
  state.ws = ws;

  let buffer = '';
  const decoder = new TextDecoder('utf-8');

  ws.onopen = function () {
    sys('Socket open. Registering…');
    setStatus('registering');
    register();
  };

  ws.onmessage = function (ev) {
    const chunk = typeof ev.data === 'string' ? ev.data : decoder.decode(ev.data, { stream: true });
    buffer += chunk;
    let idx;
    while ((idx = buffer.search(/\r\n|\n|\r/)) >= 0) {
      const line = buffer.slice(0, idx);
      buffer = buffer.slice(idx + (buffer.substr(idx, 2) === '\r\n' ? 2 : 1));
      if (line) handleLine(line);
    }
  };

  ws.onerror = function () {
    errline(null, 'WebSocket error. The server must accept WebSocket connections ' +
      'on ' + s.server + ':' + s.port + (s.tls ? ' over TLS.' : '.'));
  };

  ws.onclose = function (ev) {
    state.ws = null;
    setStatus('offline');
    state.tabs.forEach(function (t) { if (t.type === 'channel') t.joined = false; updateBadge(t); });
    sys('Disconnected' + (ev.reason ? ': ' + ev.reason : ev.code ? ' (code ' + ev.code + ')' : '') + '.');
    if (!state.quitting) sys('Use /connect to reconnect, or ☰ to change settings.');
  };
}

function disconnect(silent) {
  if (state.ws) {
    const ws = state.ws;
    state.ws = null;
    ws.onclose = null;
    ws.onerror = null;
    ws.onmessage = null;
    try { ws.close(); } catch (e) { /* ignore */ }
    if (!silent) {
      setStatus('offline');
      sys('Disconnected.');
    }
  }
}

function send(line) {
  if (!state.ws || state.ws.readyState !== WebSocket.OPEN) {
    errline(state.active, 'Not connected.');
    return false;
  }
  state.ws.send(line + '\r\n');
  return true;
}

function register() {
  const s = state.settings;
  send('CAP LS 302');
  state.caps.negotiating = true;
  if (s.pass) send('PASS ' + s.pass);
  send('NICK ' + s.nick);
  send('USER ' + (s.nick.replace(/[^A-Za-z0-9_\-]/g, '') || 'user') + ' 0 * :' +
       (s.realname || 'OnePageIRC user'));
}

/* ------------------------------------------------------------ handlers */

function handleLine(line) {
  const msg = parseLine(line);
  if (msg.tags['time']) {
    const t = new Date(msg.tags['time']);
    if (!isNaN(t.getTime())) msg.time = t;
  }
  const fn = handlers[msg.command];
  if (fn) fn(msg);
  else if (/^\d\d\d$/.test(msg.command)) numericFallback(msg);
  else sys(line, 'raw');
}

function isSelf(nick) { return ircLower(nick) === ircLower(state.nick); }

function mentionsMe(text) {
  const n = ircLower(state.nick);
  if (!n) return false;
  const t = ircLower(text);
  let i = t.indexOf(n);
  while (i >= 0) {
    const before = i === 0 ? '' : t.charAt(i - 1);
    const after = t.charAt(i + n.length);
    const wordish = /[a-z0-9_\-\[\]\\^{}|`]/;
    if (!wordish.test(before) && !wordish.test(after)) return true;
    i = t.indexOf(n, i + 1);
  }
  return false;
}

const handlers = {};

handlers['PING'] = function (msg) {
  send('PONG :' + (msg.params[0] || ''));
};

handlers['PONG'] = function () { /* silent */ };

handlers['ERROR'] = function (msg) {
  errline(null, 'Server error: ' + (msg.params[0] || ''));
};

handlers['CAP'] = function (msg) {
  const sub = (msg.params[1] || '').toUpperCase();
  const payload = msg.params[msg.params.length - 1] || '';

  if (sub === 'LS' || sub === 'NEW') {
    const more = msg.params[2] === '*';
    payload.split(' ').filter(Boolean).forEach(function (item) {
      const eq = item.indexOf('=');
      const name = eq < 0 ? item : item.slice(0, eq);
      state.caps.available[name] = eq < 0 ? true : item.slice(eq + 1);
    });
    if (more) return;
    const s = state.settings;
    const want = WANTED_CAPS.filter(function (c) {
      if (!(c in state.caps.available)) return false;
      if (c === 'sasl') return !!(s.sasluser && s.saslpass);
      if (c === 'echo-message') return false;   /* we echo locally instead */
      return true;
    });
    if (want.length) {
      state.caps.requested = want.length;
      sys('Capabilities: requesting ' + want.join(' '));
      send('CAP REQ :' + want.join(' '));
    } else if (state.caps.negotiating) {
      state.caps.negotiating = false;
      send('CAP END');
    }
  } else if (sub === 'ACK') {
    payload.split(' ').filter(Boolean).forEach(function (c) { state.caps.enabled[c] = true; });
    if (state.caps.enabled['sasl'] && state.caps.negotiating) {
      send('AUTHENTICATE PLAIN');
    } else if (state.caps.negotiating) {
      state.caps.negotiating = false;
      send('CAP END');
    }
  } else if (sub === 'NAK') {
    sys('Capabilities refused: ' + payload);
    if (state.caps.negotiating) { state.caps.negotiating = false; send('CAP END'); }
  } else if (sub === 'DEL') {
    payload.split(' ').filter(Boolean).forEach(function (c) { delete state.caps.enabled[c]; });
  } else if (sub === 'LIST') {
    sys('Capabilities enabled: ' + payload);
  }
};

handlers['AUTHENTICATE'] = function (msg) {
  if (msg.params[0] !== '+') return;
  const s = state.settings;
  const payload = b64utf8(s.sasluser + '\0' + s.sasluser + '\0' + s.saslpass);
  /* Chunk at 400 bytes per the SASL-over-IRC convention. */
  let rest = payload;
  if (!rest.length) { send('AUTHENTICATE +'); return; }
  while (rest.length >= 400) { send('AUTHENTICATE ' + rest.slice(0, 400)); rest = rest.slice(400); }
  send('AUTHENTICATE ' + (rest.length ? rest : '+'));
};

function saslDone(msg, ok) {
  sys((ok ? 'SASL: ' : 'SASL failed: ') + (msg.params[msg.params.length - 1] || ''));
  if (state.caps.negotiating) { state.caps.negotiating = false; send('CAP END'); }
}
handlers['903'] = function (m) { saslDone(m, true); };
handlers['900'] = function (m) { sys(m.params[m.params.length - 1] || ''); };
handlers['904'] = function (m) { saslDone(m, false); };
handlers['905'] = function (m) { saslDone(m, false); };
handlers['906'] = function (m) { saslDone(m, false); };
handlers['907'] = function (m) { saslDone(m, false); };

handlers['001'] = function (msg) {
  state.nick = msg.params[0] || state.nick;
  state.serverName = msg.prefix || state.settings.server;
  setStatus('online');
  sys(msg.params[1] || 'Connected.');
  /* Auto-join normally waits for the end of the MOTD; this is the backstop
     for servers that never send one. */
  setTimeout(afterMotd, 4000);
};

handlers['005'] = function (msg) {
  const tokens = msg.params.slice(1, -1);
  tokens.forEach(function (tok) {
    const eq = tok.indexOf('=');
    const key = (eq < 0 ? tok : tok.slice(0, eq)).toUpperCase();
    const val = eq < 0 ? '' : tok.slice(eq + 1);
    if (key === 'PREFIX') {
      const m = /^\(([^)]*)\)(.*)$/.exec(val);
      if (m) state.isupport.PREFIX = { modes: m[1], prefixes: m[2] };
    } else if (key === 'CHANTYPES' && val) {
      state.isupport.CHANTYPES = val;
    } else if (key === 'CHANMODES' && val) {
      state.isupport.CHANMODES = val.split(',');
    } else if (key === 'NETWORK' && val) {
      state.network = val;
      updateChrome();
    }
  });
  sys(tokens.join(' '));
};

handlers['332'] = function (msg) {           /* RPL_TOPIC */
  const tab = createTab('channel', msg.params[1]);
  setTopic(tab, msg.params[2] || '');
};

handlers['333'] = function (msg) {           /* topic author/time */
  const tab = getTab('channel', msg.params[1]);
  if (!tab) return;
  const when = Number(msg.params[3]);
  event(tab, 'Topic set by ' + msg.params[2] +
    (when ? ' on ' + new Date(when * 1000).toLocaleString() : ''));
};

handlers['353'] = function (msg) {           /* RPL_NAMREPLY */
  const chan = msg.params[2];
  const tab = createTab('channel', chan);
  const prefixes = state.isupport.PREFIX.prefixes;
  (msg.params[3] || '').split(' ').filter(Boolean).forEach(function (entry) {
    let p = '';
    let i = 0;
    while (i < entry.length && prefixes.indexOf(entry[i]) >= 0) p += entry[i++];
    let nick = entry.slice(i);
    const bang = nick.indexOf('!');
    if (bang > 0) nick = nick.slice(0, bang);   /* userhost-in-names */
    if (nick) addUser(tab, nick, p);
  });
};

handlers['366'] = function (msg) {           /* end of NAMES */
  const tab = getTab('channel', msg.params[1]);
  if (tab && tab === state.active) renderUsers();
};

handlers['331'] = function (msg) {
  const tab = getTab('channel', msg.params[1]);
  if (tab) setTopic(tab, '');
};

handlers['433'] = function (msg) {           /* nick in use */
  if (state.status === 'online') {
    errline(state.active, 'Nickname ' + msg.params[1] + ' is already in use.');
    return;
  }
  state.nickTries++;
  const base = state.settings.nick.slice(0, 12);
  const alt = state.nickTries <= 3 ? base + '_'.repeat(state.nickTries)
                                   : base + Math.floor(Math.random() * 10000);
  sys('Nickname in use, trying ' + alt);
  state.nick = alt;
  send('NICK ' + alt);
};

handlers['JOIN'] = function (msg) {
  const chan = msg.params[0];
  const tab = createTab('channel', chan);
  if (isSelf(msg.nick)) {
    tab.joined = true;
    tab.users.clear();
    updateBadge(tab);
    activateTab(tab);
    event(tab, 'You joined ' + chan);
    send('MODE ' + chan);
  } else {
    addUser(tab, msg.nick, '');
    const account = state.caps.enabled['extended-join'] && msg.params[1] && msg.params[1] !== '*'
      ? ' (' + msg.params[1] + ')' : '';
    event(tab, msg.nick + ' [' + msg.user + '@' + msg.host + ']' + account + ' joined');
  }
};

handlers['PART'] = function (msg) {
  const chan = msg.params[0];
  const tab = getTab('channel', chan);
  if (!tab) return;
  const reason = msg.params[1] ? ' (' + msg.params[1] + ')' : '';
  if (isSelf(msg.nick)) {
    tab.joined = false;
    tab.users.clear();
    updateBadge(tab);
    event(tab, 'You left ' + chan + reason);
    if (tab === state.active) renderUsers();
  } else {
    removeUser(tab, msg.nick);
    event(tab, msg.nick + ' left' + reason);
  }
};

handlers['KICK'] = function (msg) {
  const tab = getTab('channel', msg.params[0]);
  if (!tab) return;
  const who = msg.params[1];
  const reason = msg.params[2] ? ' (' + msg.params[2] + ')' : '';
  if (isSelf(who)) {
    tab.joined = false;
    tab.users.clear();
    updateBadge(tab);
    event(tab, 'You were kicked by ' + msg.nick + reason);
    if (tab === state.active) renderUsers();
  } else {
    removeUser(tab, who);
    event(tab, who + ' was kicked by ' + msg.nick + reason);
  }
};

handlers['QUIT'] = function (msg) {
  const reason = msg.params[0] ? ' (' + msg.params[0] + ')' : '';
  forEachChannelWith(msg.nick, function (tab) {
    removeUser(tab, msg.nick);
    event(tab, msg.nick + ' quit' + reason);
  });
  const q = getTab('query', msg.nick);
  if (q) event(q, msg.nick + ' quit' + reason);
};

handlers['NICK'] = function (msg) {
  const to = msg.params[0];
  const me = isSelf(msg.nick);
  if (me) {
    state.nick = to;
    updateChrome();
    sys('You are now known as ' + to);
  }
  forEachChannelWith(msg.nick, function (tab) {
    const u = getUser(tab, msg.nick);
    removeUser(tab, msg.nick);
    addUser(tab, to, u ? u.prefixes : '');
    event(tab, (me ? 'You are' : msg.nick + ' is') + ' now known as ' + to);
  });
  const q = getTab('query', msg.nick);
  if (q) {
    event(q, msg.nick + ' is now known as ' + to);
    if (!getTab('query', to)) renameTab(q, to);
  }
};

handlers['TOPIC'] = function (msg) {
  const tab = getTab('channel', msg.params[0]);
  if (!tab) return;
  setTopic(tab, msg.params[1] || '');
  event(tab, msg.nick + ' changed the topic');
};

function setTopic(tab, topic) {
  tab.topic = topic;
  tab.topicEl.hidden = !topic;
  tab.topicEl.replaceChildren();
  if (topic) {
    tab.topicEl.appendChild(document.createTextNode('Topic: '));
    tab.topicEl.appendChild(formatBody(topic));
  }
}

handlers['MODE'] = function (msg) {
  const target = msg.params[0];
  const rest = msg.params.slice(1);
  if (isChannel(target)) {
    const tab = getTab('channel', target);
    if (!tab) return;
    applyChannelModes(tab, rest);
    event(tab, (msg.nick || 'server') + ' sets mode ' + rest.join(' '));
  } else {
    sys('Mode ' + target + ' ' + rest.join(' '));
  }
};

handlers['324'] = function (msg) {           /* RPL_CHANNELMODEIS */
  const tab = getTab('channel', msg.params[1]);
  if (tab) event(tab, 'Channel modes: ' + msg.params.slice(2).join(' '));
};

function modeTakesParam(mode, adding) {
  const p = state.isupport.PREFIX.modes;
  if (p.indexOf(mode) >= 0) return true;
  const cm = state.isupport.CHANMODES;
  if ((cm[0] || '').indexOf(mode) >= 0) return true;
  if ((cm[1] || '').indexOf(mode) >= 0) return true;
  if ((cm[2] || '').indexOf(mode) >= 0) return adding;
  return false;
}

function applyChannelModes(tab, args) {
  const spec = args[0] || '';
  let argi = 1;
  let adding = true;
  const pm = state.isupport.PREFIX.modes;
  const pp = state.isupport.PREFIX.prefixes;
  for (let i = 0; i < spec.length; i++) {
    const c = spec[i];
    if (c === '+') { adding = true; continue; }
    if (c === '-') { adding = false; continue; }
    const needsArg = modeTakesParam(c, adding);
    const arg = needsArg ? args[argi++] : null;
    const pi = pm.indexOf(c);
    if (pi >= 0 && arg) {
      const u = getUser(tab, arg);
      if (u) {
        const ch = pp.charAt(pi);
        if (adding) {
          if (u.prefixes.indexOf(ch) < 0) u.prefixes += ch;
        } else {
          u.prefixes = u.prefixes.split(ch).join('');
        }
      }
    }
  }
  if (tab === state.active) scheduleUsers();
}

handlers['AWAY'] = function (msg) {           /* away-notify */
  const away = msg.params.length > 0;
  forEachChannelWith(msg.nick, function (tab) {
    const u = getUser(tab, msg.nick);
    if (u) u.away = away;
    if (tab === state.active) scheduleUsers();
  });
};

handlers['CHGHOST'] = function () { /* cosmetic only */ };
handlers['ACCOUNT'] = function () { /* cosmetic only */ };

handlers['INVITE'] = function (msg) {
  sys(msg.nick + ' invites you to ' + msg.params[msg.params.length - 1]);
};

handlers['PRIVMSG'] = function (msg) { messageIn(msg, false); };
handlers['NOTICE'] = function (msg) { messageIn(msg, true); };

function messageIn(msg, isNotice) {
  const target = msg.params[0] || '';
  let text = msg.params[1] || '';

  /* CTCP */
  if (text.charCodeAt(0) === 1) {
    text = text.replace(/\x01/g, '');
    const sp = text.indexOf(' ');
    const verb = (sp < 0 ? text : text.slice(0, sp)).toUpperCase();
    const rest = sp < 0 ? '' : text.slice(sp + 1);
    if (verb === 'ACTION') {
      deliver(msg, target, rest, 'action', isNotice);
      return;
    }
    if (isNotice) {
      sys('CTCP reply from ' + msg.nick + ': ' + verb + ' ' + rest);
      return;
    }
    ctcpRequest(msg.nick, verb, rest);
    return;
  }
  deliver(msg, target, text, isNotice ? 'notice' : 'message', isNotice);
}

function ctcpRequest(from, verb, rest) {
  sys('CTCP ' + verb + ' from ' + from);
  const reply = function (body) { send('NOTICE ' + from + ' :\x01' + body + '\x01'); };
  if (verb === 'PING') reply('PING ' + rest);
  else if (verb === 'VERSION') reply('VERSION OnePageIRC (web) — AI Sloperator / Claude Code');
  else if (verb === 'TIME') reply('TIME ' + new Date().toString());
  else if (verb === 'CLIENTINFO') reply('CLIENTINFO ACTION CLIENTINFO PING SOURCE TIME VERSION');
  else if (verb === 'SOURCE') reply('SOURCE https://www.aisloperator.com/');
}

function deliver(msg, target, text, kind, isNotice) {
  const fromMe = isSelf(msg.nick);
  let tab;

  if (isChannel(target)) {
    tab = createTab('channel', target);
  } else if (fromMe) {
    /* echo-message style: our own message to someone */
    tab = createTab('query', target);
  } else if (isNotice) {
    tab = getTab('query', msg.nick) || systemTab();
  } else {
    tab = createTab('query', msg.nick);
  }

  const hl = !fromMe && (kind !== 'notice') &&
             (tab.type === 'query' || mentionsMe(text));

  if (kind === 'action') {
    print(tab, 'action', '', msg.nick + ' ' + text, { time: msg.time, highlight: hl, nick: msg.nick });
  } else if (kind === 'notice') {
    print(tab, 'notice', '-' + msg.nick + '-', text, { time: msg.time, nick: msg.nick });
  } else {
    print(tab, fromMe ? 'message self' : 'message', msg.nick, text,
          { time: msg.time, highlight: hl, nick: msg.nick });
  }
  if (!fromMe) bump(tab, hl);
}

/* whois and other informational numerics land in the system tab */
const NUMERIC_TO_ACTIVE = {
  '401': 1, '402': 1, '403': 1, '404': 1, '405': 1, '412': 1, '421': 1,
  '442': 1, '443': 1, '461': 1, '462': 1, '471': 1, '473': 1, '474': 1,
  '475': 1, '477': 1, '482': 1
};

function numericFallback(msg) {
  const params = msg.params.slice(1);
  const text = params.join(' ');
  const code = msg.command;

  if (code === '372' || code === '375' || code === '376' || code === '422') {
    print(systemTab(), 'motd', '', text);
    if (code === '376' || code === '422') afterMotd();
    return;
  }
  if (NUMERIC_TO_ACTIVE[code]) {
    const chanParam = params.find(function (p) { return isChannel(p); });
    errline(chanParam ? (getTab('channel', chanParam) || state.active) : state.active, text);
    return;
  }
  if (code >= '400' && code <= '599') { errline(systemTab(), text); return; }
  print(systemTab(), 'system', '*', text);
}

let motdSeen = false;
function afterMotd() {
  if (motdSeen) return;
  motdSeen = true;
  if (state.settings.away) send('AWAY :' + state.settings.away);
  state.pendingJoin.forEach(function (c) {
    send('JOIN ' + (c.charAt(0).match(/[A-Za-z0-9]/) ? '#' + c : c));
  });
  state.pendingJoin = [];
}

/* Some servers send no MOTD terminator quirks; join once we are online too. */
handlers['376'] = function (msg) { numericFallback(msg); };
handlers['422'] = function (msg) { numericFallback(msg); };

/* --------------------------------------------------------- commands */

const commands = {};

function defc(names, help, fn) {
  names.split(' ').forEach(function (n, i) {
    commands[n] = { run: fn, help: i === 0 ? help : null, primary: names.split(' ')[0] };
  });
}

function currentTarget() {
  const t = state.active;
  return t && t.type !== 'system' ? t.name : null;
}

defc('join j', '/join #channel [key] — join a channel', function (args) {
  if (!args) return errline(state.active, 'Usage: /join #channel [key]');
  const parts = args.split(/\s+/);
  let chan = parts[0];
  if (!isChannel(chan)) chan = '#' + chan;
  send('JOIN ' + chan + (parts[1] ? ' ' + parts[1] : ''));
  activateTab(createTab('channel', chan));
});

defc('part leave', '/part [#channel] [reason] — leave a channel', function (args) {
  const parts = args ? args.split(/\s+/) : [];
  let chan = parts.length && isChannel(parts[0]) ? parts.shift() : currentTarget();
  if (!chan || !isChannel(chan)) return errline(state.active, 'Not in a channel.');
  send('PART ' + chan + (parts.length ? ' :' + parts.join(' ') : ''));
});

defc('cycle hop', '/cycle — part and rejoin the current channel', function () {
  const chan = currentTarget();
  if (!chan || !isChannel(chan)) return errline(state.active, 'Not in a channel.');
  send('PART ' + chan);
  send('JOIN ' + chan);
});

defc('msg m', '/msg target text — send a message', function (args) {
  const sp = args.indexOf(' ');
  if (sp < 1) return errline(state.active, 'Usage: /msg target text');
  const target = args.slice(0, sp);
  const text = args.slice(sp + 1);
  sendMessage(target, text);
});

defc('query q', '/query nick [text] — open a private tab', function (args) {
  const sp = args.indexOf(' ');
  const target = sp < 0 ? args : args.slice(0, sp);
  if (!target) return errline(state.active, 'Usage: /query nick [text]');
  const tab = createTab(isChannel(target) ? 'channel' : 'query', target);
  activateTab(tab);
  if (sp > 0) sendMessage(target, args.slice(sp + 1));
});

defc('me', '/me action — send an action', function (args) {
  const target = currentTarget();
  if (!target) return errline(state.active, 'No conversation here.');
  if (!args) return;
  if (send('PRIVMSG ' + target + ' :\x01ACTION ' + args + '\x01')) {
    const tab = state.active;
    print(tab, 'action', '', state.nick + ' ' + args, { nick: state.nick });
  }
});

defc('notice', '/notice target text — send a notice', function (args) {
  const sp = args.indexOf(' ');
  if (sp < 1) return errline(state.active, 'Usage: /notice target text');
  const target = args.slice(0, sp);
  const text = args.slice(sp + 1);
  if (send('NOTICE ' + target + ' :' + text)) {
    print(targetTab(target), 'notice', '>' + target + '<', text, { nick: state.nick });
  }
});

defc('nick n', '/nick newnick — change your nickname', function (args) {
  if (!args) return errline(state.active, 'Usage: /nick newnick');
  send('NICK ' + args.split(/\s+/)[0]);
});

defc('topic t', '/topic [text] — show or set the channel topic', function (args) {
  const chan = currentTarget();
  if (!chan || !isChannel(chan)) return errline(state.active, 'Not in a channel.');
  send('TOPIC ' + chan + (args ? ' :' + args : ''));
});

defc('names', '/names — refresh the user list', function () {
  const chan = currentTarget();
  if (!chan || !isChannel(chan)) return errline(state.active, 'Not in a channel.');
  const tab = getTab('channel', chan);
  if (tab) { tab.users.clear(); renderUsers(); }
  send('NAMES ' + chan);
});

defc('whois w', '/whois nick — look up a user', function (args) {
  const n = args ? args.split(/\s+/)[0] : currentTarget();
  if (!n) return errline(state.active, 'Usage: /whois nick');
  send('WHOIS ' + n);
});

defc('who', '/who target', function (args) { send('WHO ' + (args || currentTarget() || '')); });
defc('list', '/list [pattern] — list channels', function (args) { send('LIST' + (args ? ' ' + args : '')); });
defc('invite', '/invite nick [#channel]', function (args) {
  const parts = args.split(/\s+/);
  const chan = parts[1] || currentTarget();
  if (!parts[0] || !chan) return errline(state.active, 'Usage: /invite nick [#channel]');
  send('INVITE ' + parts[0] + ' ' + chan);
});

defc('kick', '/kick nick [reason]', function (args) {
  const chan = currentTarget();
  if (!chan || !isChannel(chan)) return errline(state.active, 'Not in a channel.');
  const parts = args.split(/\s+/);
  const who = parts.shift();
  if (!who) return errline(state.active, 'Usage: /kick nick [reason]');
  send('KICK ' + chan + ' ' + who + (parts.length ? ' :' + parts.join(' ') : ''));
});

defc('mode', '/mode [target] modes — set modes', function (args) {
  if (!args) return errline(state.active, 'Usage: /mode [target] +modes');
  const parts = args.split(/\s+/);
  if (isChannel(parts[0]) || parts[0] === state.nick) send('MODE ' + args);
  else {
    const chan = currentTarget();
    if (!chan) return errline(state.active, 'Usage: /mode target +modes');
    send('MODE ' + chan + ' ' + args);
  }
});

function modeShortcut(flag, adding) {
  return function (args) {
    const chan = currentTarget();
    if (!chan || !isChannel(chan)) return errline(state.active, 'Not in a channel.');
    const nicks = (args || '').split(/\s+/).filter(Boolean);
    if (!nicks.length) return errline(state.active, 'Usage: /' + (adding ? '' : 'de') + 'op nick…');
    send('MODE ' + chan + ' ' + (adding ? '+' : '-') + flag.repeat(nicks.length) + ' ' + nicks.join(' '));
  };
}
defc('op', '/op nick… — grant operator', modeShortcut('o', true));
defc('deop', '/deop nick…', modeShortcut('o', false));
defc('voice', '/voice nick…', modeShortcut('v', true));
defc('devoice', '/devoice nick…', modeShortcut('v', false));

defc('away', '/away [reason] — set or clear away', function (args) {
  send('AWAY' + (args ? ' :' + args : ''));
  sys(args ? 'You are away: ' + args : 'You are no longer away.');
});

defc('ctcp', '/ctcp target COMMAND [args]', function (args) {
  const parts = args.split(/\s+/);
  const target = parts.shift();
  const verb = (parts.shift() || '').toUpperCase();
  if (!target || !verb) return errline(state.active, 'Usage: /ctcp target COMMAND');
  send('PRIVMSG ' + target + ' :\x01' + verb + (parts.length ? ' ' + parts.join(' ') : '') + '\x01');
});

defc('ping', '/ping [target] — CTCP ping', function (args) {
  const target = args ? args.split(/\s+/)[0] : currentTarget();
  if (!target) return send('PING :' + Date.now());
  send('PRIVMSG ' + target + ' :\x01PING ' + Date.now() + '\x01');
});

defc('nickserv ns', '/nickserv text — message NickServ', function (args) { sendService('NickServ', args); });
defc('chanserv cs', '/chanserv text — message ChanServ', function (args) { sendService('ChanServ', args); });
defc('memoserv ms', '/memoserv text', function (args) { sendService('MemoServ', args); });

function sendService(name, args) {
  if (!args) return errline(state.active, 'Usage: /' + name.toLowerCase() + ' command…');
  if (send('PRIVMSG ' + name + ' :' + args)) {
    print(systemTab(), 'message self', state.nick + ' → ' + name, args, { nick: state.nick });
  }
}

defc('raw quote', '/raw LINE — send a raw protocol line', function (args) {
  if (!args) return errline(state.active, 'Usage: /raw COMMAND args');
  if (send(args)) sys('>> ' + args, 'raw');
});

defc('server connect', '/server [host [port]] — (re)connect', function (args) {
  if (args) {
    const parts = args.split(/\s+/);
    state.settings.server = parts[0];
    if (parts[1]) state.settings.port = parts[1];
    saveSettings();
  }
  motdSeen = false;
  connect();
});

defc('disconnect', '/disconnect — close the connection', function () {
  state.quitting = true;
  if (state.ws) { try { send('QUIT :Disconnecting'); } catch (e) {} }
  disconnect(false);
});

defc('quit', '/quit [message] — quit IRC', function (args) {
  state.quitting = true;
  send('QUIT :' + (args || 'OnePageIRC'));
  setTimeout(function () { disconnect(false); }, 250);
});

defc('close wc', '/close — close the current tab', function () { closeTab(state.active); });

defc('clear', '/clear — clear this tab', function () {
  const tab = state.active;
  tab.log.replaceChildren();
  tab.log.appendChild(tab.topicEl);
});

defc('settings', '/settings — open the connection dialog', function () { openDialog(); });

defc('help h', '/help — list commands', function () {
  sys('Commands:');
  const seen = {};
  Object.keys(commands).forEach(function (name) {
    const c = commands[name];
    if (!c.help || seen[c.help]) return;
    seen[c.help] = 1;
    print(systemTab(), 'system', '', '  ' + c.help, { plain: true });
  });
  print(systemTab(), 'system', '', '  Anything else starting with / is sent to the server as-is.', { plain: true });
});

function sendMessage(target, text) {
  if (!text) return;
  text.split('\n').forEach(function (part) {
    if (!part) return;
    if (send('PRIVMSG ' + target + ' :' + part)) {
      const tab = createTab(isChannel(target) ? 'channel' : 'query', target);
      print(tab, 'message self', state.nick, part, { nick: state.nick });
    }
  });
}

function runCommand(name, args) {
  const c = commands[name.toLowerCase()];
  if (c) { c.run(args || ''); return; }
  if (send(name.toUpperCase() + (args ? ' ' + args : ''))) {
    sys('>> ' + name.toUpperCase() + (args ? ' ' + args : ''), 'raw');
  }
}

function submitInput(raw) {
  const text = raw.replace(/\s+$/, '');
  if (!text) return;
  state.history.push(text);
  if (state.history.length > 100) state.history.shift();
  state.histIndex = -1;

  if (text.charAt(0) === '/' && text.charAt(1) !== '/') {
    const sp = text.search(/\s/);
    const name = (sp < 0 ? text.slice(1) : text.slice(1, sp));
    const args = sp < 0 ? '' : text.slice(sp + 1).replace(/^\s+/, '');
    runCommand(name, args);
    return;
  }

  const body = text.charAt(0) === '/' ? text.slice(1) : text;
  const target = currentTarget();
  if (!target) {
    errline(systemTab(), 'This is the server tab. Use /join #channel or /msg nick text.');
    return;
  }
  sendMessage(target, body);
}

/* ------------------------------------------------------------- input */

function autoGrow() {
  ui.input.style.height = 'auto';
  ui.input.style.height = Math.min(ui.input.scrollHeight, 104) + 'px';
}

ui.composer.addEventListener('submit', function (ev) {
  ev.preventDefault();
  submitInput(ui.input.value);
  ui.input.value = '';
  autoGrow();
});

ui.input.addEventListener('input', autoGrow);

ui.input.addEventListener('keydown', function (ev) {
  if (ev.key === 'Enter' && !ev.shiftKey && !ev.altKey) {
    ev.preventDefault();
    submitInput(ui.input.value);
    ui.input.value = '';
    autoGrow();
    return;
  }
  if (ev.key === 'Tab') { ev.preventDefault(); complete(); return; }
  if (ev.key === 'ArrowUp' && ui.input.selectionStart === 0) { ev.preventDefault(); historyStep(-1); return; }
  if (ev.key === 'ArrowDown' && ui.input.selectionStart === ui.input.value.length) {
    if (state.histIndex >= 0) { ev.preventDefault(); historyStep(1); }
    return;
  }
  if (ev.key === 'Escape') { ui.input.value = ''; autoGrow(); }
});

function historyStep(dir) {
  const h = state.history;
  if (!h.length) return;
  if (state.histIndex === -1) {
    if (dir > 0) return;
    state.histDraft = ui.input.value;
    state.histIndex = h.length - 1;
  } else {
    state.histIndex += dir;
  }
  if (state.histIndex < 0) state.histIndex = 0;
  if (state.histIndex >= h.length) { state.histIndex = -1; ui.input.value = state.histDraft; autoGrow(); return; }
  ui.input.value = h[state.histIndex];
  autoGrow();
  const n = ui.input.value.length;
  ui.input.setSelectionRange(n, n);
}

let completion = null;

function applyCompletion() {
  const c = completion;
  const pick = c.candidates[c.index];
  const next = c.head + pick + c.tail;
  ui.input.value = next;
  const caret = c.head.length + pick.length;
  ui.input.setSelectionRange(caret, caret);
  c.value = next;
  c.caret = caret;
  autoGrow();
}

function complete() {
  const value = ui.input.value;
  const pos = ui.input.selectionStart;

  /* A second Tab without any other editing cycles through the candidates. */
  if (completion && completion.value === value && completion.caret === pos) {
    completion.index = (completion.index + 1) % completion.candidates.length;
    applyCompletion();
    return;
  }

  const before = value.slice(0, pos);
  const m = /([^\s]*)$/.exec(before);
  const word = m[1];
  const start = pos - word.length;

  let candidates;
  if (start === 0 && word.charAt(0) === '/') {
    const stem = word.slice(1).toLowerCase();
    candidates = Object.keys(commands)
      .filter(function (c) { return c.indexOf(stem) === 0; })
      .sort()
      .map(function (c) { return '/' + c + ' '; });
  } else {
    const tab = state.active;
    const stem = ircLower(word);
    const names = [];
    if (tab && tab.type === 'channel') tab.users.forEach(function (u) { names.push(u.nick); });
    else if (tab && tab.type === 'query') names.push(tab.name);
    candidates = names
      .filter(function (n) { return !stem || ircLower(n).indexOf(stem) === 0; })
      .sort(function (a, b) { return ircLower(a) < ircLower(b) ? -1 : 1; })
      .map(function (n) { return n + (start === 0 ? ': ' : ' '); });
  }
  if (!candidates.length) return;

  completion = {
    head: value.slice(0, start),
    tail: value.slice(pos),
    index: 0,
    candidates: candidates,
    value: '',
    caret: -1
  };
  applyCompletion();
}

ui.input.addEventListener('blur', function () { completion = null; });
ui.input.addEventListener('click', function () { completion = null; });

/* ---------------------------------------------------------- settings */

function defaults() {
  return {
    server: 'irc.libera.chat',
    port: '6667',
    nick: randomNick(),
    tls: location.protocol === 'https:',
    path: '/',
    proto: '',
    realname: 'OnePageIRC user',
    channels: '',
    pass: '',
    sasluser: '',
    saslpass: '',
    away: ''
  };
}

function loadSettings() {
  const d = defaults();
  let saved = null;
  try { saved = JSON.parse(localStorage.getItem(STORE_KEY) || 'null'); } catch (e) { saved = null; }
  if (!saved) return d;
  Object.keys(d).forEach(function (k) {
    if (typeof saved[k] === typeof d[k] && saved[k] !== '') d[k] = saved[k];
    else if (k === 'channels' || k === 'path') d[k] = saved[k] != null ? saved[k] : d[k];
  });
  /* Passwords are never persisted. */
  d.pass = '';
  d.saslpass = '';
  return d;
}

function saveSettings() {
  const s = state.settings;
  const copy = {
    server: s.server, port: s.port, nick: s.nick, tls: s.tls, path: s.path,
    proto: s.proto, realname: s.realname, channels: s.channels, sasluser: s.sasluser
  };
  try { localStorage.setItem(STORE_KEY, JSON.stringify(copy)); } catch (e) { /* private mode */ }
}

function fillDialog(s) {
  $('#f-server').value = s.server;
  $('#f-port').value = s.port;
  $('#f-nick').value = s.nick;
  $('#f-tls').checked = !!s.tls;
  $('#f-path').value = s.path;
  $('#f-proto').value = s.proto;
  $('#f-realname').value = s.realname;
  $('#f-channels').value = s.channels;
  $('#f-pass').value = s.pass;
  $('#f-sasluser').value = s.sasluser;
  $('#f-saslpass').value = s.saslpass;
  updateNote();
}

function readDialog() {
  return {
    server: $('#f-server').value.trim().replace(/^\w+:\/\//, '').replace(/\/.*$/, ''),
    port: $('#f-port').value.trim(),
    nick: $('#f-nick').value.trim(),
    tls: $('#f-tls').checked,
    path: $('#f-path').value.trim() || '/',
    proto: $('#f-proto').value,
    realname: $('#f-realname').value.trim() || 'OnePageIRC user',
    channels: $('#f-channels').value.trim(),
    pass: $('#f-pass').value,
    sasluser: $('#f-sasluser').value.trim(),
    saslpass: $('#f-saslpass').value,
    away: ''
  };
}

function updateNote() {
  const s = readDialog();
  const lines = [];
  lines.push('A web page cannot open a raw TCP socket, so this client speaks IRC over ' +
             'a WebSocket. The endpoint must accept WebSocket connections.');
  lines.push('Target: ' + wsUrl(s));
  if (location.protocol === 'https:' && !s.tls) {
    lines.push('⚠ This page was loaded over HTTPS, so the browser will block a plain ' +
               'ws:// connection. Enable "Secure WebSocket" or serve this page over http:// / file://.');
  }
  ui.dlgNote.textContent = lines.join(' ');
}

['#f-server', '#f-port', '#f-path'].forEach(function (sel) {
  $(sel).addEventListener('input', updateNote);
});
$('#f-tls').addEventListener('change', updateNote);

function openDialog() {
  fillDialog(state.settings);
  ui.dlgError.hidden = true;
  if (typeof ui.dialog.showModal === 'function') ui.dialog.showModal();
  else ui.dialog.setAttribute('open', '');
}

function closeDialog() {
  if (typeof ui.dialog.close === 'function') ui.dialog.close();
  else ui.dialog.removeAttribute('open');
}

ui.btnMenu.addEventListener('click', openDialog);

ui.btnCancel.addEventListener('click', function () {
  if (!booted) return;               /* nothing to go back to yet */
  closeDialog();
});

/* Escape must not leave the user staring at an empty page. */
ui.dialog.addEventListener('cancel', function (ev) {
  if (!booted) ev.preventDefault();
});

ui.form.addEventListener('submit', function (ev) {
  ev.preventDefault();
  const s = readDialog();
  if (!s.server) return showDialogError('Enter a server host name.');
  if (!/^\d{1,5}$/.test(s.port) || Number(s.port) < 1 || Number(s.port) > 65535) {
    return showDialogError('Enter a port between 1 and 65535.');
  }
  if (!/^[A-Za-z\[\]\\`_^{|}][A-Za-z0-9\[\]\\`_^{|}\-]{0,29}$/.test(s.nick)) {
    return showDialogError('Nicknames start with a letter and contain letters, digits, - _ [ ] \\ ` ^ { | }.');
  }
  state.settings = s;
  saveSettings();
  closeDialog();
  boot();
  motdSeen = false;
  connect();
});

function showDialogError(text) {
  ui.dlgError.textContent = text;
  ui.dlgError.hidden = false;
}

/* -------------------------------------------------------------- boot */

let booted = false;
function boot() {
  if (booted) return;
  booted = true;
  ui.app.hidden = false;
  const t = createTab('system', 'Server');
  activateTab(t);
  sys('OnePageIRC — static, dependency-free IRC client.');
  sys('Generated by AI Sloperator (https://www.aisloperator.com/) using Claude Code.');
  sys('Type /help for the command list. Tab completes nicknames and commands.');
  sys('Note: browsers cannot open raw TCP, so this connects over WebSocket. ' +
      'The server or a gateway in front of it must accept WebSocket connections.');
}

/* Keep the layout matched to the visual viewport so the iOS software keyboard
   does not cover the composer. */
function fitViewport() {
  const vv = window.visualViewport;
  const h = vv ? vv.height : window.innerHeight;
  document.documentElement.style.setProperty('--app-h', h + 'px');
  if (window.scrollY !== 0) window.scrollTo(0, 0);
  if (state.active && state.active.stick) scrollDown(state.active);
}

if (window.visualViewport) {
  window.visualViewport.addEventListener('resize', fitViewport);
  window.visualViewport.addEventListener('scroll', fitViewport);
}
window.addEventListener('resize', function () {
  fitViewport();
  if (window.innerWidth >= 700 && state.active && state.active.type === 'channel') {
    usersVisible = true;
  }
  updateChrome();
  renderUsers();
});
window.addEventListener('orientationchange', function () { setTimeout(fitViewport, 200); });

/* A vertical wheel over the tab strip scrolls it sideways. */
ui.tabbar.addEventListener('wheel', function (ev) {
  if (Math.abs(ev.deltaY) <= Math.abs(ev.deltaX)) return;
  ui.tabbar.scrollLeft += ev.deltaY;
  ev.preventDefault();
}, { passive: false });

document.addEventListener('visibilitychange', function () {
  if (document.visibilityState === 'visible' && state.active) {
    state.active.unread = 0;
    state.active.hl = false;
    updateBadge(state.active);
  }
});

window.addEventListener('beforeunload', function () {
  if (state.ws && state.ws.readyState === WebSocket.OPEN) {
    state.quitting = true;
    try { state.ws.send('QUIT :OnePageIRC\r\n'); } catch (e) { /* ignore */ }
  }
});

/* Left/right swipe between tabs on touch screens. */
(function swipes() {
  let x0 = null, y0 = null, t0 = 0;
  ui.views.addEventListener('touchstart', function (ev) {
    if (ev.touches.length !== 1) { x0 = null; return; }
    x0 = ev.touches[0].clientX;
    y0 = ev.touches[0].clientY;
    t0 = Date.now();
  }, { passive: true });
  ui.views.addEventListener('touchend', function (ev) {
    if (x0 == null || !ev.changedTouches.length) return;
    const dx = ev.changedTouches[0].clientX - x0;
    const dy = ev.changedTouches[0].clientY - y0;
    x0 = null;
    if (Date.now() - t0 > 600) return;
    if (Math.abs(dx) < 70 || Math.abs(dy) > 50) return;
    const i = state.tabs.indexOf(state.active);
    const next = state.tabs[i + (dx < 0 ? 1 : -1)];
    if (next) activateTab(next);
  }, { passive: true });
})();

state.settings = loadSettings();
fitViewport();
openDialog();

})();
